use vstd::prelude::*;

verus! {

    /// Remove the k-th element (1-based) from a non-empty vector of i32's,
    /// where 1 <= k < list.len().  The result has length `list.len() - 1`
    /// and preserves the order of all other elements.
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
        requires
            // list is non-empty and we cannot remove the last element
            list.len() > 1,
            // 1-based index k, strictly less than the length
            1 <= k && k < list.len(),
        ensures
            // new_list has exactly one fewer element
            new_list.len() == list.len() - 1,
            // every element before position k−1 is the same
            forall|i: usize| i < k - 1 ==> new_list[i] == list[i],
            // every element at and after position k−1 is list[i+1]
            forall|i: usize| k - 1 <= i && i < new_list.len() ==> new_list[i] == list[i + 1],
    {
        let n = list.len();
        let skip = k - 1; // convert to 0-based index

        // Build the result by pushing every element except at `skip`.
        let mut new_list: Vec<i32> = Vec::with_capacity(n - 1);
        let mut i: usize = 0;

        while i < n
            invariant
                // i walks from 0 up to n
                i <= n,
                // the current length of new_list is i, minus one if we've passed skip
                new_list.len() == if i <= skip { i } else { i - 1 },
                // I've already proved that for every j < new_list.len(),
                // if j < skip then new_list[j] == list[j],
                // otherwise new_list[j] == list[j+1].
                forall|j: usize| j < new_list.len() ==>
                    if j < skip {
                        new_list[j] == list[j]
                    } else {
                        new_list[j] == list[j + 1]
                    },
            decreases n - i
        {
            if i != skip {
                new_list.push(list[i]);
            }
            i += 1;
        }

        // At i == n, the invariants give us new_list.len() == n - 1
        // and the positional equalities, exactly as in the postcondition.
        new_list
    }
}

